        #include "json_parser.h"

int get_json_value(const char* json_str, int json_len, char* value_out, int out_size) {
    if (!json_str || !value_out || json_len <= 0 || out_size <= 0) {
        return -1;
    }

    // Find the start of the value (skip whitespace and quotes)
    int i = 0;
    while (i < json_len && (json_str[i] == ' ' || json_str[i] == '\t' || json_str[i] == '\n' || json_str[i] == '\r')) {
        i++;
    }

    // Check if value is quoted
    int start = i;
    if (json_str[i] == '"') {
        start = i + 1;
        i++;
        // Find the closing quote
        while (i < json_len && json_str[i] != '"') {
            i++;
        }
    } else {
        // For unquoted values, find the end
        while (i < json_len && json_str[i] != ',' && json_str[i] != '}' && json_str[i] != ']') {
            i++;
        }
    }

    // Calculate the length of the value
    int value_len = i - start;
    if (json_str[i] == '"') {
        value_len--; // Exclude the closing quote
    }

    // Check if the output buffer is large enough
    if (value_len >= out_size) {
        return -1; // Buffer too small
    }

    // Copy the value to the output buffer
    memcpy(value_out, json_str + start, value_len);
    value_out[value_len] = '\0'; // Null terminate

    return value_len; // Return the length of the copied value
}
